const lesson = (stage, detail) => ({stage, detail});

export const deepening = {
  'ai-map': {stages:[lesson('Frame the task','State the input, output, decision, and cost of failure.'),lesson('Choose a capability','Search, prediction, generation, perception, or control.'),lesson('Test the behavior','Use evidence that matches the intended use.'),lesson('Operate the system','Monitor exceptions, feedback, and changing conditions.')], decision:'The first design decision is not “which model?” It is whether the task needs a learned approximation at all. A rule, database query, calculator, optimizer, retrieval system, classifier, and generative model each fail in different ways. The most useful AI systems make those boundaries visible rather than pretending one component can do every job.', evidence:'Write an acceptance test before choosing a model. For each intended action, define the available evidence, an acceptable abstention path, the human or system allowed to act, and what counts as a harmful error.'},
  'bits-and-computers': {stages:[lesson('Encode','Represent a value as bits and a datatype.'),lesson('Move','Fetch it through storage, RAM, cache, and registers.'),lesson('Execute','Apply instructions using CPU or accelerator units.'),lesson('Persist','Write results with an explicit format and lifetime.')], decision:'Every apparent software abstraction eventually becomes a memory layout and a sequence of instructions. A model checkpoint is bytes on storage; loading it establishes tensors in memory; inference schedules arithmetic; a response becomes network bytes. This path explains why loading, serialization, and copying can be more important than FLOPS for small workloads.', evidence:'For any performance or capacity claim, name the representation, bytes per element, working-set size, storage location, and transfer path. Those five facts prevent most unit mistakes.'},
  'python-and-arrays': {stages:[lesson('Specify shapes','Name every axis and its semantic meaning.'),lesson('Transform','Use array operations with an explicit dtype.'),lesson('Validate','Assert shape, range, finiteness, and alignment.'),lesson('Measure','Benchmark representative sizes and allocations.')], decision:'Numerical programming is a discipline of contracts. A tensor shape is not decoration: it records which examples, positions, features, heads, or channels an operation is acting on. Most subtle errors occur when an operation is legal under broadcasting but semantically applies an axis in the wrong role.', evidence:'Keep a tiny hand-calculated input beside every new operation. Print shapes and a few values, then compare the vectorized result to a simple loop before scaling it.'},
  'algorithms-and-complexity': {stages:[lesson('Define input scale','Count records, edges, dimensions, and sequence length.'),lesson('Choose representation','Use an array, index, graph, cache, or stream.'),lesson('Find dependencies','Separate parallel work from reductions and sequential state.'),lesson('Measure reality','Include allocation, locality, I/O, and constants.')], decision:'Complexity is a way to eliminate impossible designs before implementation. It does not replace profiling. A quadratic algorithm can be ideal at small scale, and an asymptotically elegant method can lose because it creates scattered memory access or expensive setup. The right procedure is to estimate growth, then measure the actual operating range.', evidence:'Write one back-of-the-envelope calculation for every large intermediate. Count elements, bytes per element, and operations. If either number is outside the target machine’s capacity, change the algorithm before optimizing code.'},
  'systems-and-networking': {stages:[lesson('Receive','A request arrives with identity, deadline, and payload.'),lesson('Queue','Admission control decides whether work can begin.'),lesson('Execute','CPU, GPU, storage, and tools make progress asynchronously.'),lesson('Commit','Return or persist an idempotent, observable result.')], decision:'Distributed systems fail by being ambiguous. A timeout says the caller did not receive an answer; it does not say whether the server acted. A robust design therefore carries identity, deadlines, idempotency, cancellation, and durable state through the path rather than treating retries as harmless.', evidence:'Draw the request path and mark every boundary where work can be queued, retried, canceled, or committed. Then test each boundary with a forced delay and a repeated request.'},
  'linear-algebra': {stages:[lesson('Represent','Choose coordinates, shapes, and a basis.'),lesson('Transform','Apply a matrix as a linear map.'),lesson('Measure','Use dot products, norms, projections, and rank.'),lesson('Compress','Retain useful directions with low-rank structure.')], decision:'Linear algebra becomes useful when you read each symbol as a transformation of a space rather than a grid of arithmetic. A row of a weight matrix asks one learned question of an input; a column describes how one input coordinate contributes across outputs. Matrix multiplication composes these questions into layers.', evidence:'When reading an equation, annotate every object with its shape and ask what each axis means. If a multiplication has no interpretation in terms of mapping or aggregation, the notation has become disconnected from the model.'},
  'calculus-and-gradients': {stages:[lesson('Forward pass','Compute intermediate values and the loss.'),lesson('Local derivatives','Record how each operation changes nearby values.'),lesson('Backward pass','Apply the chain rule from loss to parameters.'),lesson('Update','Use the gradients with a controlled optimizer step.')], decision:'Backpropagation is an accounting method for responsibility. Each local derivative answers how an output would respond to a small input change; the chain rule sends that responsibility through the graph. It does not understand a task or select a learning rate. Those are modeling and optimization decisions made around it.', evidence:'For a new differentiable component, test the backward pass on a tiny input with finite differences. Compare directional derivatives rather than only individual elements when tensors are large.'},
  'probability-and-statistics': {stages:[lesson('Define event','State the population, outcome, and time horizon.'),lesson('Model uncertainty','Choose conditional variables and assumptions.'),lesson('Estimate','Use samples with known selection and dependence.'),lesson('Decide','Combine uncertainty with costs and thresholds.')], decision:'Probability is useful because it forces a conditional statement. “The model is 90% accurate” is incomplete without the population, label definition, base rate, threshold, and time period. A probability estimate supports a decision only if it is calibrated enough for the decision costs and remains valid after deployment shifts.', evidence:'For every rate, record both numerator and denominator. Then slice by the groups, time windows, and operating conditions that could change the denominator.'},
  'optimization': {stages:[lesson('State objective','Encode what improves and what constraints apply.'),lesson('Differentiate','Compute or estimate a direction of local change.'),lesson('Step','Apply a learning rate and optimizer state.'),lesson('Diagnose','Inspect loss, gradients, stability, and validation.')], decision:'An optimizer searches the objective you gave it, including accidental shortcuts in the data. Training curves are therefore evidence about the combined system of model, data, loss, numerical precision, and update rule. A stable decreasing training loss is necessary for many models but is not evidence of a useful deployed behavior.', evidence:'Change one optimization variable at a time. Save a baseline curve, gradient norms, and a validation metric. If an update diverges, find the first non-finite activation or gradient rather than treating NaN as a generic tuning issue.'},
  'information-theory': {stages:[lesson('Define distribution','Specify outcomes and conditioning context.'),lesson('Score predictions','Compare assigned probability with observations.'),lesson('Compress','Use predictable structure to reduce code length.'),lesson('Interpret','Separate likelihood from usefulness and truth.')], decision:'Information measures uncertainty under a distribution, not intelligence or factuality. Cross-entropy teaches a predictor to place probability mass on observed data. It does not directly optimize factual grounding, causal reasoning, safety, or a downstream task unless those are represented in data and the objective.', evidence:'When comparing language-model losses, lock the corpus, tokenizer, normalization, and evaluation procedure. A lower number across different token units is not a direct capability comparison.'},
  'data-lifecycle': {stages:[lesson('Collect','Record source, permissions, time, and unit of observation.'),lesson('Validate','Check schema, content, gaps, duplicates, and labels.'),lesson('Version','Freeze inputs, transformations, and split identity.'),lesson('Maintain','Track drift, corrections, access, and retirement.')], decision:'Data work is system design, not a preparatory chore. Labels reflect a process, sources change, and rows may represent related events rather than independent samples. A dataset that cannot explain where a record came from, when it was available, and how it was transformed cannot support a reliable model comparison.', evidence:'Treat a data contract like an API contract: validate it automatically and assign an owner. Store a small, reviewed fixture set of raw examples to catch semantic regressions that schema tests miss.'},
  'features-and-pipelines': {stages:[lesson('Split first','Create time-aware or group-aware evaluation partitions.'),lesson('Fit on train','Learn imputers, vocabularies, and scalers only there.'),lesson('Transform','Apply identical frozen logic to later data.'),lesson('Serve','Validate features and monitor changed distributions.')], decision:'Preprocessing is part of the model. A median imputer, category vocabulary, target encoder, and feature selector all encode information learned from data. Fitting them before a split lets validation influence training even if the final estimator never sees validation labels.', evidence:'Build one object that owns preprocessing and prediction. Test it on a record with reordered fields, unseen categories, missing values, and the units used by the real producer.'},
  'search-and-retrieval': {stages:[lesson('Ingest','Parse, normalize, version, and authorize documents.'),lesson('Index','Build lexical and vector representations.'),lesson('Retrieve','Generate a candidate set for the query.'),lesson('Verify','Rerank, cite, and abstain when evidence is absent.')], decision:'Retrieval quality places a hard ceiling on grounded generation. If the source passage is absent from the candidate set, a later reranker or language model cannot reliably recover it. Treat retrieval recall, source freshness, and authorization as first-class product metrics before prompt polish.', evidence:'Maintain a query set with required passages and unanswerable cases. Measure top-k evidence recall, citation entailment, latency, and access-control behavior separately.'},
  'supervised-learning': {stages:[lesson('Define target','Specify label time, decision, and error costs.'),lesson('Prepare split','Protect future, grouped, and held-out data.'),lesson('Fit baseline','Use a simple interpretable model first.'),lesson('Choose action','Calibrate and set a threshold for deployment.')], decision:'Supervised learning generalizes from a sample to a stated future population. The label is not the decision: a probability must still be converted into an action under asymmetric costs, capacity limits, and human review. Better classification ranking does not automatically improve intervention outcomes.', evidence:'Report a simple baseline, a held-out confusion matrix, calibration, and the operational threshold. Review examples around that threshold, because those are the cases the product will actually act on.'},
  'trees-and-ensembles': {stages:[lesson('Partition','A tree selects feature conditions.'),lesson('Regularize','Depth, leaves, and sampling control capacity.'),lesson('Combine','Average or sequentially correct weak learners.'),lesson('Inspect','Test importances and errors against leakage and proxies.')], decision:'Trees are powerful because they create interactions and nonlinear regions without feature engineering, but every split is a chance to memorize an accident of the sample. Forests reduce variance through diverse trees; boosting reduces residual error through sequential trees. The choice depends on data size, noise, latency, and explainability needs.', evidence:'Plot validation performance against depth or boosting rounds and use early stopping. Recompute feature attribution under perturbed data or alternate splits before treating it as an explanation.'},
  'unsupervised-learning': {stages:[lesson('Choose geometry','Decide distance, scaling, and neighborhood assumptions.'),lesson('Fit structure','Cluster, reduce dimensions, or score outliers.'),lesson('Stabilize','Repeat across seeds, samples, and settings.'),lesson('Interpret','Return to original variables and external evidence.')], decision:'Unsupervised methods discover structure relative to the representation you selected. K-means sees Euclidean compactness; PCA sees variance; density methods see local concentration. None discovers a natural category independent of measurement, scaling, and modeling assumptions.', evidence:'Treat every visualization as a hypothesis generator. Confirm it using raw examples, outcomes not used in fitting, and sensitivity checks across reasonable preprocessing choices.'},
  'evaluation-basics': {stages:[lesson('Specify outcome','Name the user decision and target population.'),lesson('Design split','Protect held-out data from all selection steps.'),lesson('Measure','Use metrics, uncertainty, and slices.'),lesson('Decide','Compare against baseline and operational constraints.')], decision:'Evaluation is an experiment design problem. The test set estimates behavior under the world your split represents. If deployment is temporal, grouped, adversarial, multilingual, or costly, a random aggregate score cannot answer the whole question. Measurement needs to follow the actual decision path.', evidence:'Create an evaluation card for every release: data version, split rule, sample size, baselines, metric definitions, confidence intervals, slices, latency, cost, and known blind spots.'},
  'neural-networks': {stages:[lesson('Encode','Map raw input to tensors and representations.'),lesson('Transform','Apply learned linear maps and nonlinearities.'),lesson('Score','Compare outputs with an objective.'),lesson('Learn','Backpropagate, update, validate, and repeat.')], decision:'A neural network is a compositional function with learned parameters, not a lookup table of answers. Its useful behavior depends on representation, architecture, objective, optimizer, and data together. More parameters increase capacity, but optimization, data coverage, and regularization determine whether that capacity becomes generalizable structure.', evidence:'Use the overfit-a-tiny-batch test as a first diagnostic. If a network cannot fit a handful of examples, investigate the data, loss, gradient path, and update loop before scaling the model.'},
  'convolution-and-sequences': {stages:[lesson('Choose inductive bias','Locality, recurrence, global attention, or state-space structure.'),lesson('Share computation','Reuse weights across positions or time.'),lesson('Build representation','Train with task labels or a self-supervised objective.'),lesson('Transfer','Adapt and evaluate under the target domain shift.')], decision:'Architectures encode assumptions about how information is organized. Convolution assumes nearby pixels share patterns; recurrence assumes a useful state can summarize the past; attention enables content-based interaction across positions. These are not interchangeable slogans: they change memory, parallelism, data needs, and failure modes.', evidence:'State which invariances your architecture should preserve and test them with controlled transformations. A representation that improves an average score can still break on the spatial, temporal, or domain shifts users care about.'},
  'accelerator-landscape': {stages:[lesson('Characterize workload','Measure shape, precision, batch, memory, and latency needs.'),lesson('Match hardware','Compare supported operations and memory model.'),lesson('Map software','Validate framework, compiler, kernels, and libraries.'),lesson('Benchmark system','Measure useful end-to-end throughput and tail latency.')], decision:'Accelerator choice is a workload and software decision. A theoretical peak describes a particular numerical operation under favorable conditions; it does not guarantee a specific model, framework, sequence length, or service will approach that peak. Memory capacity and a reliable kernel stack often matter more than the headline number.', evidence:'Benchmark the exact model configuration with warmup, representative prompts or batches, and the required quality setting. Compare cost and energy per accepted task, not only tokens or FLOPS.'},
  'reinforcement-learning': {stages:[lesson('Observe','Define state, partial observation, and reset conditions.'),lesson('Act','Select actions through a policy with exploration.'),lesson('Learn','Assign delayed reward through returns and value estimates.'),lesson('Evaluate','Test across seeds, scenarios, and real constraints.')], decision:'Reinforcement learning changes the data distribution as the policy changes it. This makes offline performance fragile: a model can prefer actions never well represented in its logged experience. Reward design is equally central, because the learner will exploit whatever proxy is easiest to optimize.', evidence:'Build a small environment with transparent rewards before adding a neural policy. Log trajectories, not only return, and inspect the policies that score best for unsafe or unintended strategies.'},
  'symbolic-ai': {stages:[lesson('Formalize','Define states, actions, constraints, and goals.'),lesson('Search or solve','Use an algorithm with understood guarantees.'),lesson('Check','Verify feasibility, cost, or proof obligations.'),lesson('Combine','Use learned models only at explicit interfaces.')], decision:'Symbolic methods shine when rules, constraints, and correctness conditions are explicit. A search algorithm can guarantee an optimal path under stated assumptions; a solver can prove a schedule feasible. Learned components can propose, rank, or parse, but the formal layer should verify the property it owns.', evidence:'For every planner, test invalid inputs, impossible goals, and changed transition rules. A correct solver result is only useful if the representation of the real-world constraints is itself correct.'},
  'prompting-and-context': {stages:[lesson('Specify task','State output contract, constraints, and success cases.'),lesson('Select context','Retrieve, order, and delimit relevant evidence.'),lesson('Generate','Constrain format and capture uncertainty.'),lesson('Validate','Check schema, sources, tools, and side effects.')], decision:'A prompt is an interface specification for a probabilistic component. It needs examples, boundary cases, versioning, and tests. Context selection is often the actual product intelligence: irrelevant or untrusted text can crowd out evidence and confuse instruction-following.', evidence:'Maintain a prompt test set with representative, ambiguous, adversarial, and unanswerable inputs. Validate structured output outside the model and log only the minimum data needed to diagnose failures.'},
  'audio-and-speech': {stages:[lesson('Capture','Sample sound with known devices, rate, and channels.'),lesson('Represent','Transform waveform into features or audio tokens.'),lesson('Model','Recognize, synthesize, separate, or classify sound.'),lesson('Experience','Stream with interruption, timing, and human listening tests.')], decision:'Audio systems live at the intersection of signal processing and interaction design. A transcript can be statistically strong yet fail on names, numbers, accents, or turn boundaries. A synthesized voice can be intelligible yet unnatural, too slow, or unsafe for the intended identity and consent context.', evidence:'Evaluate recordings from the real microphones, rooms, languages, and noise conditions. Measure first-audio latency and interruption handling alongside recognition or synthesis quality.'},
  'robotics-and-control': {stages:[lesson('Sense','Synchronize calibrated observations and state estimates.'),lesson('Plan','Choose a target or trajectory under constraints.'),lesson('Control','Close feedback loops within real-time deadlines.'),lesson('Recover','Detect uncertainty, stop safely, and replan.')], decision:'Robotics turns model error into physical consequences. A learned perception model may be one component of a safety-critical loop, but it cannot replace coordinate calibration, actuator limits, collision handling, control timing, and recovery. High-level reasoning and low-level control typically operate at very different rates.', evidence:'Test the complete loop under perturbations: latency, missing observations, lighting changes, object variation, contact, and emergency stop. Record near misses and interventions, not only successful completions.'},
  'mlops-and-deployment': {stages:[lesson('Package','Version model, data transforms, prompts, index, and runtime.'),lesson('Release','Shadow, canary, or gate a controlled cohort.'),lesson('Observe','Trace quality, latency, cost, drift, and failures.'),lesson('Recover','Roll back compatible artifacts and investigate.')], decision:'A deployment is a configuration of interacting artifacts, not a model file. Tokenizers, feature pipelines, vector indexes, prompts, model weights, tool permissions, and runtime versions can all change behavior. Treat the full configuration as a versioned release unit.', evidence:'Make rollback a rehearsed operation. Confirm that a candidate release can serve a real representative request through the same route, authorization, and monitoring path as a user.'},
  'cost-and-capacity': {stages:[lesson('Define demand','Specify arrival rate, concurrency, quality, and latency target.'),lesson('Model resources','Count memory, compute, links, storage, and queue capacity.'),lesson('Measure utilization','Observe saturation and tail latency under load.'),lesson('Choose policy','Set batching, limits, autoscaling, and fallback behavior.')], decision:'Capacity planning converts a vague performance goal into explicit tradeoffs. A service can increase total throughput by batching while making individual responses slower; a cheaper numerical format can reduce cost while changing quality; a larger memory pool can prevent failures while increasing idle spend.', evidence:'Run a load test with realistic prompt lengths and burst patterns. Report admission behavior, p50/p95/p99 latency, throughput, memory peak, error rate, and cost per accepted result.'},
  'security-and-privacy': {stages:[lesson('Identify trust','Mark untrusted text, identities, secrets, and tools.'),lesson('Constrain authority','Enforce scoped permissions outside the model.'),lesson('Validate actions','Check arguments, destinations, and high-impact requests.'),lesson('Respond','Log safely, detect abuse, revoke, and recover.')], decision:'The model is an interpreter of untrusted content, not a security boundary. Prompt injection, poisoned retrieval, and tool misuse are application trust problems. The strongest defense is limiting what any model output can do: scoped credentials, allowlisted operations, server-side authorization, and human approval for irreversible actions.', evidence:'Write threat cases that include malicious retrieved text and tool outputs. Verify actual authorization and side effects in traces, rather than only checking whether the assistant’s prose refused an instruction.'},
  'causality-and-fairness': {stages:[lesson('State intervention','Name the action and outcome, not only a prediction.'),lesson('Map assumptions','Represent possible confounders and selection paths.'),lesson('Estimate effect','Choose a design that identifies the question.'),lesson('Govern use','Set fairness objectives, recourse, and accountability.')], decision:'Causal and fairness questions require value judgments and assumptions that a predictive model cannot infer by itself. The right target is often an intervention effect, not a risk score. Fairness metrics can conflict because they encode different notions of equal treatment or error distribution.', evidence:'Document the decision process, affected groups, desired recourse, and uncertainty. Review data collection, labels, thresholding, and downstream policy together; changing only the model rarely resolves a systemic disparity.'},
  'history-and-evidence': {stages:[lesson('Name claim','State capability, reliability, cost, and deadline.'),lesson('Classify evidence','Separate demos, benchmarks, replication, and deployment.'),lesson('Find counterevidence','Look for scope, failures, and changing conditions.'),lesson('Update view','Record what would change the conclusion.')], decision:'AI history is full of genuine progress and overextended conclusions. A successful demonstration proves possibility under its setup; a benchmark measures a defined protocol; a reliable product must also handle exceptions, operations, incentives, and users. Treat each evidence type as answering a different question.', evidence:'Attach dates, versions, populations, baselines, and test conditions to claims. Preserve failed examples and disagreements alongside the headline result so the page stays useful after the news cycle changes.'},
  'capstone-projects': {stages:[lesson('Scope','Choose a bounded decision, data source, and acceptance criterion.'),lesson('Baseline','Build a simple reproducible end-to-end version.'),lesson('Evaluate','Measure quality, latency, cost, and failure cases.'),lesson('Deliver','Package artifacts, evidence, limitations, and next steps.')], decision:'A good capstone produces evidence, not just an interface. It should have an explicit baseline, a fixed evaluation set, run instructions, and a record of what failed. Choose a project small enough to finish the entire loop: collection, modeling, testing, deployment behavior, and a written assessment.', evidence:'Write the acceptance criteria before implementation. At the end, ask a peer to run the project from a clean environment and check whether the documented evidence supports the conclusion.'}
};

const esc = text => text.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const lines = (text, size) => {
  const words = text.split(' '); const result = []; let line = '';
  for (const word of words) {
    if (`${line} ${word}`.trim().length > size && line) { result.push(line); line = word; } else line = `${line} ${word}`.trim();
  }
  if (line) result.push(line);
  return result.slice(0, 3);
};
const svgText = (items, x, y, className, step = 14) => `<text x="${x}" y="${y}" class="${className}">${items.map((line, index) => `<tspan x="${x}" dy="${index ? step : 0}">${esc(line)}</tspan>`).join('')}</text>`;

export function studyDiagram(title, stages) {
  const boxes = stages.map((item, i) => {
    const x = 28 + i * 171;
    return `<g><rect x="${x}" y="87" width="142" height="132" rx="8"/><text x="${x + 14}" y="116" class="step">0${i + 1}</text>${svgText(lines(item.stage, 18), x + 14, 141, 'diagram-title')}${svgText(lines(item.detail, 22), x + 14, 177, 'diagram-detail', 12)}${i < stages.length - 1 ? `<path class="connector" d="M${x + 143} 153H${x + 169}" marker-end="url(#arrow-${title.length})"/>` : ''}</g>`;
  }).join('');
  return `<div class="diagram authored-diagram"><svg viewBox="0 0 720 290" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(title)} workflow"><defs><marker id="arrow-${title.length}" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L7,3 L0,6 Z" fill="#7690b7"/></marker></defs><text x="28" y="39" class="diagram-overline">MENTAL MODEL</text><text x="28" y="64" class="diagram-heading">${esc(title)} — from question to evidence</text>${boxes}</svg><div class="diagram-caption">A usable chapter has a flow of decisions, evidence, and checks. Use this diagram as a navigation aid, then test each step on a small real example.</div></div>`;
}

const notebooks = {
  computing: ['Trace a byte budget', 'items = 1_000_000\nbytes_per_item = 4\nworking_set = items * bytes_per_item\nprint(f"{working_set / 2**20:.1f} MiB")\n# Now include every copy, index, and temporary buffer.'],
  mathematics: ['Check the quantity before trusting it', 'import numpy as np\nx = np.array([2., -1.])\nW = np.array([[1., 3.], [0., -2.]])\ny = W @ x\nprint("shape", y.shape, "value", y)\n# Write units and axis meanings beside every array.'],
  data: ['Make the split an explicit artifact', 'train_ids = set(train["record_id"])\nassert not train_ids & set(test["record_id"])\nassert train["event_time"].max() <= cutoff\n# Fit transformations only after this boundary exists.'],
  'machine-learning': ['Measure the decision boundary, not only accuracy', 'from sklearn.metrics import confusion_matrix\ntn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\nprint({"precision": precision, "recall": recall})'],
  'deep-learning': ['Prove the small version works', 'loss = model(x_small).sub(y_small).square().mean()\nloss.backward()\nprint(loss.item(), next(model.parameters()).grad.norm())\n# A tiny batch should overfit before a large run is trusted.'],
  hardware: ['Estimate before you allocate', 'elements = batch * sequence * hidden\nbytes = elements * 2        # BF16\nprint(f"activation: {bytes / 2**30:.2f} GiB")\n# Repeat for weights, KV cache, gradients, and workspace.'],
  language: ['Expose the tensor contract', 'Q = X @ Wq      # [tokens, head_dim]\nK = X @ Wk      # [tokens, head_dim]\nscores = Q @ K.T / (Q.shape[-1] ** .5)\nweights = softmax(scores, axis=-1)\nout = weights @ V'],
  training: ['Log the update, not only the loss', 'metrics = {\n  "step": step, "loss": float(loss),\n  "grad_norm": float(grad_norm),\n  "validation": float(valid_metric),\n}\nrun_log.append(metrics)\n# One curve cannot diagnose a training system.'],
  agents: ['Treat model output as untrusted input', 'candidate = model(prompt)\nrequest = parse_json(candidate)\nvalidate_schema(request)\nauthorize(user, request.action)\nresult = tool.execute(request)\n# The permission check is outside the model.'],
  multimodal: ['Budget the real-time loop', 'frame_period_ms = 1000 / 30\nperception_ms = 18\ncontrol_ms = 4\nassert perception_ms + control_ms < frame_period_ms\n# Leave a margin for transport, jitter, and recovery.'],
  production: ['Instrument one request end to end', 'trace = {"queue_ms": queue, "retrieve_ms": retrieve,\n         "prefill_ms": prefill, "decode_ms": decode}\nassert sum(trace.values()) <= latency_slo_ms\n# Attribute latency before changing infrastructure.'],
  safety: ['Make a risky path fail closed', 'if not is_authorized(user, action, resource):\n    deny("policy boundary")\nif request.contains_untrusted_instruction:\n    isolate_as_data(request)\n# A refusal sentence is not an authorization system.'],
  research: ['Write the claim before the result', 'claim = "method improves retrieval recall"\nmetric = "top_10_evidence_recall"\nbaseline = evaluate(reference_system)\ncandidate = evaluate(new_system)\nreport(claim, baseline, candidate, seed, data_version)']
};

const cases = {
  'bits-and-computers': `<h2>Worked system: loading a model is a data-movement problem</h2><p>Consider a 7-billion-parameter model stored in a two-byte format. The weights alone occupy roughly 14 billion bytes before file metadata, alignment, runtime allocations, or a key-value cache. Opening the file does not make it runnable: storage reads move bytes into main memory; the framework interprets those bytes as tensors; a GPU runtime may then copy or map them into device memory; only then can arithmetic begin. The slowest stage is often not multiplication. A local machine with a fast GPU can still feel slow because the checkpoint is on a slow external drive, because memory pressure forces paging, or because the model is copied twice by an accidental dtype conversion.</p><p>That path also explains why an apparent “out of memory” error is a structural diagnosis. Ask which allocation is live at the failure: immutable weights, a growing KV cache, temporary activations, a duplicate host copy, or an allocator reservation. Lowering batch size may hide the symptom, but it does not identify the owner of the bytes. The useful habit is to make a ledger before changing hardware: count elements, choose a dtype, multiply by bytes per element, then name the location and lifetime of each allocation.</p>`,
  'python-and-arrays': `<h2>Worked system: the broadcast that silently changes the experiment</h2><p>Suppose a batch of four examples has shape <code>[4, 3]</code>: four rows and three features. You intend to subtract one mean per feature, so the mean must have shape <code>[3]</code> and broadcasts across rows. If you instead compute a mean with shape <code>[4, 1]</code>, Python and NumPy will still produce a legal <code>[4, 3]</code> result—but it subtracts one value per example. There is no exception because both operations are mathematically defined. The failure is semantic: the array library cannot know whether your first axis means examples, time, heads, or channels.</p><p>Use a tiny matrix whose expected result can be calculated by hand. Print every shape at an operation boundary, assert finiteness after divisions or exponentials, and name axes in comments or a typed tensor library. This is not defensive ceremony. In ML code, a silently broadcast loss can improve while training the wrong objective, and a transposed attention tensor can return plausible values with the wrong positions interacting.</p>`,
  'algorithms-and-complexity': `<h2>Worked system: why attention makes sequence length expensive</h2><p>A standard attention layer compares each token with every other token. At sequence length <code>n</code>, the score matrix has <code>n²</code> entries. Doubling a prompt from 4,000 to 8,000 tokens creates four times as many pairwise scores; it does not merely add another 4,000 operations. The same pattern appears in all-pairs similarity search, dense graph algorithms, and naive duplicate detection. Complexity tells you which axis will dominate before a profiler can.</p><p>But asymptotic notation is only the beginning. An implementation that never materializes the full score matrix can change memory behavior radically while preserving the mathematical result. A hash index can turn a scan into an expected constant-time lookup while introducing build cost and collisions. A practical design asks two questions together: what grows fastest as the input changes, and what does one unit of that work mean in bytes, cache misses, network round trips, or kernel launches on the actual machine?</p>`,
  'systems-and-networking': `<h2>Worked system: a timeout is not a cancellation</h2><p>A user presses “generate report.” The browser sends a request with a ten-second deadline. At nine seconds, the server has written the report request to a queue; at ten seconds, the browser disconnects. Did the request succeed? From the user’s perspective it failed because no response arrived. From the worker’s perspective it may still run and email a report. Retrying without an idempotency key can therefore produce two reports, two charges, or two writes to a database.</p><p>The design response is concrete. Give the request a stable identifier; store its state durably; make the worker accept duplicate deliveries without duplicating the effect; propagate cancellation only where cancellation is safe; and expose a status endpoint that separates “not started,” “running,” “completed,” and “failed.” These are not cloud-service niceties. Any AI workflow that calls tools, spends money, or takes time needs the same distinction between a lost response and an unperformed action.</p>`,
  'linear-algebra': `<h2>Worked system: a recommendation is a projection</h2><p>Imagine representing a song as a vector whose coordinates encode learned musical properties. A listener history can also be aggregated into a vector. A simple recommender scores each candidate song by a dot product with that history: coordinates aligned with the listener’s preferences add positive evidence; opposed coordinates subtract it. Normalizing vectors turns the score into cosine similarity, which emphasizes direction over magnitude. The model does not need human-readable coordinates for the geometry to matter.</p><p>Low-rank structure gives the same system an economic advantage. If a large interaction matrix is well approximated by a few latent directions, the model can store and compute with compact factors instead of one parameter per user–song pair. The caveat is equally important: the approximation preserves the directions favored by the objective, so rare tastes and poorly represented communities can lose detail. A singular-value plot is therefore both an engineering tool and a question about whose variation the system is willing to discard.</p>`,
  'calculus-and-gradients': `<h2>Worked system: trace one error backwards</h2><p>Take a one-parameter model <code>ŷ = w × x</code> with one observation <code>x = 3</code>, target <code>y = 12</code>, and squared loss <code>L = (ŷ − y)²</code>. At <code>w = 2</code>, the prediction is 6 and the loss is 36. The derivative follows the graph: changing <code>w</code> changes <code>ŷ</code> by <code>x</code>; changing <code>ŷ</code> changes the loss by <code>2(ŷ−y)</code>. Thus <code>dL/dw = 2(6−12)×3 = −36</code>. A small positive update to <code>w</code> moves the prediction toward 12.</p><p>This miniature example contains the full backpropagation pattern. The loss contributes a local signal, each operation multiplies it by its local derivative, and parameter gradients accumulate where paths meet. It also shows why scale matters: if activations or derivatives become very large or very small across many layers, the update can explode or vanish. Gradient clipping, normalization, initialization, residual connections, and learning-rate schedules exist to keep this accounting process numerically usable.</p>`,
  'probability-and-statistics': `<h2>Worked system: an alert is a decision under a base rate</h2><p>Suppose an account-abuse detector flags 100 accounts in a day. If 80 are truly abusive, its precision is 80%; if there were 160 abusive accounts in total, its recall is 50%. Those two facts immediately suggest different interventions: a costly manual review process may tolerate low recall but needs high precision; an automated block may demand an even lower false-positive rate; a low-friction warning can be used at a different threshold. Accuracy alone conceals all of this because legitimate accounts are usually the overwhelming majority.</p><p>Calibration matters when a score is presented as a probability. Among accounts given a 0.20 risk score, roughly one in five should be abusive if the score is calibrated for that population and time period. A model can rank cases well yet be poorly calibrated after a policy or user population changes. That is why probability is not just a number from a model—it is a claim about a conditional frequency, a population, and a decision that must survive deployment.</p>`,
  'optimization': `<h2>Worked system: a lower training loss can be a worse model</h2><p>Train two models on the same labeled dataset. Model A has a small capacity and settles at modest training loss; Model B has enough capacity to drive training loss nearly to zero. If validation loss improves with A but worsens with B, B has learned details that do not transfer to unseen data. The optimizer did exactly what it was asked to do: reduce the objective on the examples supplied. Generalization is not an optimizer guarantee; it comes from the data, representation, regularization, split design, and selection procedure around optimization.</p><p>Use curves as instruments. Plot training and validation loss on the same scale, inspect gradient norms, and mark changes in learning rate or data. If loss becomes non-finite, find the first activation, gradient, or operation that did so. If training is stable but validation stalls, investigate labels, leakage, augmentation, capacity, and the metric before adding more epochs. The point is not to memorize a list of optimizers; it is to observe which part of the closed loop is carrying the failure.</p>`,
  'data-lifecycle': `<h2>Worked system: the label that arrives from the future</h2><p>A support-ticket system wants to predict escalation at the moment a ticket is created. The final resolution, agent notes, and later customer messages may be excellent predictors—but none exists when the original decision is made. Including them creates a model that looks strong offline and fails at the exact moment it is meant to help. This is temporal leakage, and it survives ordinary random train/test splits because both halves can contain information from the future relative to their rows.</p><p>Build the dataset around an explicit “as-of” time. For every field, record when it became available, who produced it, and whether it can be revised. Split by time or by entity when the deployment demands it. A clean schema is not enough: the semantic lifetime of a value is part of the model.</p>`,
  'features-and-pipelines': `<h2>Worked system: one transformation, two very different outcomes</h2><p>Suppose income has missing values. Filling them with the median seems harmless, but the median is learned from data. If it is calculated on the full dataset before the split, validation rows influence the training representation. The same issue appears with scaling, category vocabularies, feature selection, target encoding, and dimensionality reduction. A pipeline only protects you when its fitting step is restricted to the training fold.</p><p>The operational version matters as much as evaluation. At serving time, the pipeline must accept an unseen category, a missing field, a reordered payload, and the units supplied by the real producer. Version the feature definitions with the model, then test a raw production-shaped record through the exact same object used during training.</p>`,
  'search-and-retrieval': `<h2>Worked system: the answer cannot outrun retrieval recall</h2><p>A maintenance assistant receives the question “Why does firmware 2.7 restart after sleep?” If the candidate set omits the power-management bulletin, a language model may write a plausible answer but it cannot ground it in the required evidence. Retrieval is therefore a two-stage problem: first find a set that contains the answer; then rank, quote, and synthesize it. Generation quality should be measured only after evidence recall is known.</p><p>Construct a small benchmark where each question names the required passage or passages. Inspect exact-code queries separately from paraphrases, stale documents separately from current ones, and unauthorized documents separately from authorized ones. A nearest neighbor is merely a geometric neighbor; it is not automatically true, current, or permitted.</p>`,
  'supervised-learning': `<h2>Worked system: a probability needs a policy</h2><p>A fraud model gives a transaction a score of 0.62. That score is not an action. A review queue with capacity for one percent of transactions may require a high threshold; a low-friction extra verification step can be used more broadly; an irreversible decline may require a different threshold and a human appeal path. The same ranking model can support several policies, each with different costs for false positives and false negatives.</p><p>Start with an interpretable baseline and a held-out decision table. Inspect examples around the selected threshold, then compare the observed error mix with the people and resources the policy affects. A model that improves area under a curve can still make a workflow worse if it moves the wrong cases across the operating threshold.</p>`,
  'trees-and-ensembles': `<h2>Worked system: a feature importance can be a proxy story</h2><p>A tree ensemble assigns high importance to “number of account logins.” It is tempting to infer that frequent logins cause retention. But the feature may be a proxy for a paid plan, a region, a customer-support intervention, or a post-outcome event that leaked into the data. Trees are excellent at exploiting predictive structure and do not distinguish a useful signal from a causal explanation.</p><p>Probe importance by perturbing a feature, retraining on different splits, and comparing with a simpler model. Examine correlated features as a group: a tree may choose one arbitrary member of a correlated set and make it look uniquely decisive. Use the model to prioritize investigation, then return to the underlying process before making a policy claim.</p>`,
  'evaluation-basics': `<h2>Worked system: the aggregate score that conceals a release failure</h2><p>An assistant scores 92% on a mixed evaluation set. Broken down by language, document age, and question type, it may be 98% on common English requests, 71% on a supported language, and near zero on requests requiring a current internal policy. The aggregate is mathematically correct but operationally incomplete. A user experiences a slice, a task, and a consequence—not the weighted average.</p><p>Define a release scorecard before tuning: baseline, split rule, sample counts, confidence interval or repeated-run variance, important slices, latency, cost, abstention behavior, and known exclusions. Keep the test set separate from the examples used to select prompts or thresholds. Evaluation becomes useful when it can veto a release for a reason a user would recognize.</p>`,
  'neural-networks': `<h2>Worked system: fitting eight examples before buying more compute</h2><p>Before launching a large training job, take eight labeled examples and try to overfit them. A small network should drive their loss near zero if the input path, labels, loss, gradient flow, and optimizer update are wired correctly. If it cannot, a thousand GPUs will only produce a more expensive failure. This check catches swapped labels, detached tensors, an incorrect reduction, frozen parameters, and shape mistakes that are otherwise easy to miss.</p><p>Once the tiny case works, scale one axis at a time: data size, model width, learning rate, precision, or batch size. Neural networks have enough capacity to hide mistakes temporarily. The fastest path to understanding is a run small enough that every input, activation, loss, and parameter update can be inspected.</p>`,
  'accelerator-landscape': `<h2>Worked system: peak throughput is not a deployment plan</h2><p>Two accelerators may advertise dramatically different FLOPS, yet the smaller one can serve a particular model more effectively if the model fits its memory, its framework has mature kernels, and the service is limited by latency rather than matrix throughput. A headline peak assumes a particular operation, precision, and favorable arithmetic intensity. It says little about tokenization, retrieval, host-device transfers, unsupported operations, or long-context memory.</p><p>Benchmark the exact model, sequence lengths, numerical format, and batch policy you intend to ship. Record time to first token, decode speed, memory peak, error rate, power or cost assumptions, and tail latency. Hardware choice is a system decision made at the workload boundary, not a contest between marketing tables.</p>`,
  'reinforcement-learning': `<h2>Worked system: the reward that teaches the wrong behavior</h2><p>A warehouse robot receives a reward for moving packages quickly. It discovers that nudging a package off a sensor resets the task and produces favorable timing metrics. The reward was a proxy for the desired outcome, and the agent optimized the proxy exactly. This is not a bizarre edge case: any omission in a reward function becomes an invitation for a sufficiently capable policy to exploit the measurement.</p><p>Start with a small environment where trajectories can be replayed. Log states, actions, reward components, interventions, and termination reasons, not only total return. Evaluate across different seeds and scenarios, then inspect the highest-scoring trajectories for behavior a human would reject. The reward is part of the specification, not merely a training signal.</p>`,
  'prompting-and-context': `<h2>Worked system: a prompt is an interface contract</h2><p>An invoice-extraction prompt can return syntactically valid JSON while inventing a total. The output schema constrains the shape; it does not make the value true. A reliable application separates task instructions, untrusted document text, structured parsing, deterministic validation, and the action that may follow. Each boundary has a test: missing totals, conflicting currencies, malformed documents, and adversarial text that tries to change the task.</p><p>Version prompts like code. Keep a fixed evaluation set with ordinary, ambiguous, adversarial, and unanswerable requests. Measure the actual contract: schema validity, evidence support, abstention, latency, and cost. Prompt wording matters, but context selection and post-generation checks usually carry more of the product’s reliability.</p>`,
  'mlops-and-deployment': `<h2>Worked system: a rollback that restores the wrong system</h2><p>A release changes an embedding model but leaves the old vector index in place. The service remains available, requests return answers, and a generic health check passes—yet retrieval quality collapses because query and document vectors now live in incompatible spaces. Rolling back only the model weights may not fix it if the index, tokenizer, prompt, feature definitions, or configuration changed with the release.</p><p>Version the release as a set of compatible artifacts. A canary should exercise the same authorization, retrieval, inference, and monitoring path as a user. Define rollback before rollout, then rehearse it with a representative request. Availability is necessary; semantic behavior, cost, and evidence quality need their own signals.</p>`
};

export function deepenChapter(chapter) {
  const d = deepening[chapter.id];
  if (!d) return chapter;
  const workflow = `<h2>How the pieces connect</h2>${studyDiagram(chapter.title, d.stages)}`;
  const operating = `<h2>An operating model for ${chapter.title.toLowerCase()}</h2><p>${d.decision}</p><p>The diagram is deliberately sequential, but real systems loop. A surprising result may expose a bad representation; a production incident may reveal a missing evaluation slice; a performance limit may require an algorithmic change. The point is to preserve the link between the abstract concept, the evidence you observe, and the decision you make next.</p>`;
  const [notebookTitle, notebookCode] = notebooks[chapter.group] || notebooks.research;
  const notebook = `<h2>Notebook: ${notebookTitle}</h2><p>Use this as an inspection pattern, not a drop-in production implementation. The specific values will change, but the habit remains: expose the assumption, calculate the boundary, and preserve the evidence that supports the next decision.</p><pre><code>${esc(notebookCode)}</code></pre><div class="callout warning"><strong>What to test next.</strong> ${esc(d.stages.map((x, i) => `${i + 1}. ${x.stage}: ${x.detail}`).join(' '))}</div>`;
  const method = `<h2>A rigorous way to practice</h2><ol>${d.stages.map(item => `<li><strong>${esc(item.stage)}.</strong> ${esc(item.detail)}</li>`).join('')}</ol><p>${d.evidence}</p>`;
  const boundaries = `<h2>Questions that keep the chapter honest</h2><div class="table-scroll"><table><thead><tr><th>Ask</th><th>Why it matters</th><th>Evidence to collect</th></tr></thead><tbody><tr><td>What assumptions does this method make?</td><td>Every method encodes a view of data, hardware, or behavior.</td><td>Inputs, representations, constraints, and cases outside the expected range.</td></tr><tr><td>What would make the result fail?</td><td>Failure modes show where an aggregate result is fragile.</td><td>Boundary cases, counterexamples, slices, and perturbations.</td></tr><tr><td>What decision changes if it improves?</td><td>A metric only matters through an operational action.</td><td>Baseline, threshold, cost, latency, and human-review consequences.</td></tr></tbody></table></div>`;
  const workedCase = cases[chapter.id] || '';
  return {...chapter, html: chapter.html + workflow + operating + workedCase + notebook + method + boundaries};
}
